// Private local result export. No network; no browser profiles or credentials included.
const fs=require('node:fs'),path=require('node:path'),sharp=require('sharp')
const ROOT=path.resolve('verification/folder-20261016'),OUT=path.join(ROOT,'delivery')
const phases=[['workbench','01-视觉工作台'],['remix','02-提示词迁移'],['planner','03-一键策划'],['simple','04-图文生图']]
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')
async function main(){fs.mkdirSync(OUT,{recursive:true});const sections=[],summary=[]
 for(const[phase,title]of phases){const dir=path.join(ROOT,phase),resultFile=path.join(dir,phase==='planner'&&fs.existsSync(path.join(dir,'combined-results.json'))?'combined-results.json':'results.json');if(!fs.existsSync(resultFile))continue;const results=JSON.parse(fs.readFileSync(resultFile,'utf8')),dest=path.join(OUT,title);fs.mkdirSync(dest,{recursive:true});const suiteFile=path.join(dir,'suite.json');if(fs.existsSync(suiteFile))fs.copyFileSync(suiteFile,path.join(dest,'提示词套装.json'));fs.copyFileSync(resultFile,path.join(dest,'验证结果.json'));const rows=[],layers=[]
 for(const[i,t]of results.entries()){const n=String(i+1).padStart(2,'0');for(const suffix of ['提示词.txt','提交提示词.txt']){const f=`${n}-${suffix}`;if(fs.existsSync(path.join(dir,f)))fs.copyFileSync(path.join(dir,f),path.join(dest,f))}const images=[];for(const im of t.images){if(!im.file)continue;fs.copyFileSync(path.join(dir,im.file),path.join(dest,im.file));images.push(`<a href="${title}/${im.file}"><img loading="lazy" src="${title}/${im.file}" alt="${esc(im.file)}"></a><p>${im.width} × ${im.height}</p>`)}const expected=t.requestInfo?.submittedSize||t.requestInfo?.size;const ratioWarnings=t.images.filter(im=>{const m=/^(\d+)x(\d+)$/.exec(expected||'');return m&&Math.abs(Math.log((im.width/im.height)/(Number(m[1])/Number(m[2]))))>0.03});rows.push(`<article><h3>${n} · ${esc(t.ratio)} · ${t.images.length}/${t.count}张</h3><p>${esc(t.status)} ${esc(t.error)}</p>${ratioWarnings.length?'<strong>实际画幅与请求不符，请核查原图</strong>':''}${images.join('')}<a href="${title}/${n}-提示词.txt">完整提示词</a> · <a href="${title}/${n}-提交提示词.txt">实际提交提示词</a></article>`);for(const[j,im]of t.images.entries()){if(!im.file)continue;const k=layers.length/2;layers.push({input:await sharp(path.join(dir,im.file)).resize(320,280,{fit:'contain',background:'white'}).png().toBuffer(),left:k%4*320,top:Math.floor(k/4)*310+30});layers.push({input:Buffer.from(`<svg width="320" height="30"><rect width="320" height="30" fill="#e2e8ef"/><text x="12" y="21" font-family="Arial" font-size="16">${phase} ${n}-${j+1}</text></svg>`),left:k%4*320,top:Math.floor(k/4)*310})}}
 if(layers.length)await sharp({create:{width:1280,height:Math.ceil(layers.length/8)*310,channels:3,background:'white'}}).composite(layers).jpeg({quality:88}).toFile(path.join(ROOT,phase+'-contact.jpg'))
 summary.push({phase,tasks:results.length,expected:results.reduce((s,t)=>s+Number(t.count),0),returned:results.reduce((s,t)=>s+t.images.length,0),complete:results.filter(t=>t.images.length===Number(t.count)).length});sections.push(`<section><h2>${title}</h2><div class="grid">${rows.join('')}</div></section>`)
 }
 fs.writeFileSync(path.join(OUT,'汇总.json'),JSON.stringify(summary,null,2));fs.writeFileSync(path.join(OUT,'测试结果总览.html'),`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>20261016 实测结果</title><style>body{font:15px/1.7 system-ui;margin:24px;background:#f4f6f8;color:#18212b}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px}article{background:white;border:1px solid #ccd4dc;border-radius:12px;padding:16px;min-width:0}img{width:100%;height:280px;object-fit:contain}strong{color:#a74200}a{color:#1657b1}</style><h1>2026-10-16 真实测试结果</h1><p>点击图片查看原图；提示词完整保留。未返回和画幅不符如实标明，不裁剪、不自动重试。策划尺寸示例仅供测试，不是实测数据。</p>${sections.join('')}</html>`);console.log(JSON.stringify(summary))
}
main().catch(e=>{console.error(e.message);process.exitCode=1})
